      "kind": "chart",
      "title": "Sub-Saharan Africa has the highest Prosperity Gap and contributes the most to the Global Prosperity Gap, followed by South Asia",
      "bbox": [
        463,
        165,
        815,
        835
      ],
      "content": {
        "panel_a": {
          "title": "a. Prosperity Gap in 2024 by region",
          "type": "bar chart",
          "y_axis": "Prosperity Gap",
          "x_axis": "Regions",
          "data": {
            "Europe and Central Asia": 1.7,
            "East Asia and Pacific": 2.2,
            "Latin America and the Caribbean": 3.5,
            "Middle East and North Africa": 4.5,
            "South Asia": 6.2,
            "Sub-Saharan Africa": 12.2
          }
        },
        "panel_b": {
          "title": "b. Regional contribution to the Global Prosperity Gap and global population in 2024, percent",
          "type": "stacked bar chart",
          "y_axis": "Percent",
          "legend": [
            "East Asia and Pacific",
            "Europe and Central Asia",
            "Latin America and the Caribbean",
            "Middle East and North Africa",
            "South Asia",
            "Sub-Saharan Africa",
            "Rest of the world"
          ],
          "data": {
            "Prosperity Gap share": {
              "Sub-Saharan Africa": 39,
              "South Asia": 30,
              "East Asia and Pacific": 15,
              "Middle East and North Africa": 5,
